package cn.breezeth.kaleidoscope_grilling;
import net.minecraft.ChatFormatting; import net.minecraft.network.chat.Component; import net.minecraft.resources.ResourceLocation; import net.minecraft.world.item.Item; import net.minecraft.world.item.ItemStack; import net.minecraftforge.registries.ForgeRegistries; import java.util.List;
public final class SeasoningTooltip { public static void append(ItemStack stack, List<Component> tooltip) { List<String> values=SeasoningData.get(stack); tooltip.add(Component.translatable("tooltip.kaleidoscope_grilling.seasoning_capacity", values.size(), 8).withStyle(ChatFormatting.GRAY)); for(String id:values){Item item=ForgeRegistries.ITEMS.getValue(new ResourceLocation(id)); if(item!=null) tooltip.add(Component.literal("- ").append(item.getDescription()).withStyle(ChatFormatting.DARK_GRAY));} } private SeasoningTooltip(){} }
